package node

import (
	"encoding/hex"
	"testing"

	"github.com/ethereum/go-ethereum/common"
	"github.com/ethereum/go-ethereum/crypto"

	"tool-test/pkg/logger"
)

func TestDecodeNode(t *testing.T) {
	type args struct {
		hash []byte
		buf  []byte
	}
	tests := []struct {
		name    string
		args    args
		want    Node
		wantErr bool
	}{
		{
			name: "Test Empty DecodeNode Returns Error or Empty Node",
			args: args{
				hash: []byte(""),
				buf: common.FromHex(
					"",
				),
			},
			wantErr: false,
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, err := DecodeNode(tt.args.hash, tt.args.buf)
			if (err != nil) != tt.wantErr {
				t.Errorf("DecodeNode() error = %v, wantErr %v", err, tt.wantErr)
				return
			}
			logger.Info("got: %v", got, err)
		})
	}
}

func TestHashEmptyFullNode(t *testing.T) {
	fullNode := &FullNode{}
	bData, _ := fullNode.Marshal()
	logger.Info(hex.EncodeToString(bData))
	logger.Info(crypto.Keccak256Hash(bData))
}
